#src/nubra_python_sdk/reports/reports_enum.py
from enum import Enum


# ─────────────────────────────────────────────
# ACTION TYPE  (what the server does with the report)
# ─────────────────────────────────────────────

class ReportActionType(str, Enum):
    """
    What the backend should do with the generated report.

    VIEW      -> the report is returned as JSON (the server forces the
                 back-office export format to JSON for this action).
    DOWNLOAD  -> the report is returned as a PDF/XLSX byte stream.
    EMAIL     -> the report is mailed to the client's registered email id and
                 only an acknowledgement is returned. Not every report
                 supports it — check ``actionTypes`` in ``report_options()``.
    """
    VIEW = "VIEW"
    DOWNLOAD = "DOWNLOAD"
    EMAIL = "EMAIL"


# ─────────────────────────────────────────────
# EXPORT FORMAT  (only meaningful for DOWNLOAD/EMAIL)
# ─────────────────────────────────────────────

class ReportExportFormat(str, Enum):
    """File format for a DOWNLOAD/EMAIL action. Ignored when action is VIEW."""
    PDF = "PDF"
    EXCEL = "EXCEL"
    JSON = "JSON"


# ─────────────────────────────────────────────
# REPORT TYPE  (`type` field of GET /report)
# ─────────────────────────────────────────────

class ReportType(str, Enum):
    """
    Report identifiers served by ``report_options()``.

    Each one is generated by a single :class:`NubraReports` method — see the
    ``type`` -> method table in the :class:`NubraReports` docstring. Note two
    names differ: ``summary`` is ``financial_ledger()`` and ``holding`` is
    ``holding_statement()``.
    """
    SUMMARY = "summary"                  # Financial ledger
    PROFIT_LOSS = "profit_loss"
    DAILY_MARGIN = "daily_margin"
    DEMAT = "demat"
    CONTRACT_NOTE = "contract_note"
    HOLDING = "holding"
    OPEN_POSITIONS = "open_positions"


# ─────────────────────────────────────────────
# REPORT CATEGORY  (`category` field of GET /report)
# ─────────────────────────────────────────────

class ReportCategory(str, Enum):
    ACCOUNT_STATEMENT = "ACCOUNT_STATEMENT"
    PROFIT_LOSS = "PROFIT_LOSS"
    HOLDING = "HOLDING"


# ─────────────────────────────────────────────
# DATE RANGE OPTION  (`dateRangeOptions` field of GET /report)
# ─────────────────────────────────────────────

class ReportDateRangeOption(str, Enum):
    """Date pickers a report supports — a single date or a range."""
    DATE = "DATE"
    DATE_RANGE = "DATE_RANGE"
    FINANCIAL_YEARS = "FINANCIAL_YEARS"
    LAST_1_MONTH = "LAST_1_MONTH"
    LAST_QUARTER = "LAST_QUARTER"
